def generate_divisibility_graph(num_vertices, target_edges):
    from itertools import combinations

    # Start with powers of 2 to ensure a high number of edges due to divisibility.
    nums = [2**i for i in range(num_vertices)]

    edges = []
    for u, v in combinations(range(num_vertices), 2):
        if nums[u] % nums[v] == 0 or nums[v] % nums[u] == 0:
            edges.append([u+1, v+1])

    while len(edges) != target_edges:
        # If we have too few edges, we can replace a number with a composite that shares factors.
        if len(edges) < target_edges:
            for i in range(num_vertices):
                for j in range(i+1, num_vertices):
                    new_num = nums[i] * nums[j] // gcd(nums[i], nums[j])
                    if new_num not in nums and len(edges) + (num_vertices - 1) >= target_edges:
                        nums[i] = new_num
                        break
                else:
                    continue
                break

        # Recalculate the edges with the updated nums.
